import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display order summary before payment confirmation', async ({ page }) => {
    await page.getByRole('button', { name: /proceed to payment/i }).click();
    const orderSummary = await page.getByRole('heading', { name: /order summary/i });
    await expect(orderSummary).toBeVisible();
  });

  test('should show correct order details in summary', async ({ page }) => {
    await page.getByRole('button', { name: /proceed to payment/i }).click();
    const orderDetails = await page.getByText(/item details/i);
    await expect(orderDetails).toBeVisible();
    const totalAmount = await page.getByText(/total amount/i);
    await expect(totalAmount).toHaveText('$99.99'); // Example total amount
  });
});
